<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{{ $document === 'invoice' ? 'Invoice' : 'Packing slip' }} {{ $order->order_number }}</title><style>body{font:14px Arial,sans-serif;color:#172033;margin:0;padding:32px}.wrap{max-width:800px;margin:auto}.row{display:flex;justify-content:space-between;gap:24px}.muted{color:#64748b}.box{border:1px solid #cbd5e1;padding:16px;border-radius:8px;margin:16px 0}table{width:100%;border-collapse:collapse;margin-top:18px}th,td{border-bottom:1px solid #e2e8f0;padding:10px;text-align:left}td:last-child,th:last-child{text-align:right}.total{margin-left:auto;width:280px}.total div{display:flex;justify-content:space-between;padding:5px 0}.print{padding:10px 16px;background:#0f172a;color:white;border:0;border-radius:6px}@media print{body{padding:0}.print{display:none}@page{size:A4;margin:18mm}}</style></head><body><main class="wrap"><button class="print" onclick="window.print()">Print</button><div class="row"><div><h1>{{ $document === 'invoice' ? 'Order invoice' : 'Packing slip' }}</h1><p class="muted">{{ $store['site.name'] ?? 'Best Cool Electronics' }}</p>@if($store['contact.address'] ?? false)<p>{{ $store['contact.address'] }}</p>@endif@if($store['contact.phone'] ?? false)<p>{{ $store['contact.phone'] }}</p>@endif@if($store['contact.email'] ?? false)<p>{{ $store['contact.email'] }}</p>@endif</div><div><strong>{{ $order->order_number }}</strong><p>{{ $order->created_at?->format('d M Y, g:i a') }}</p><p>Payment: {{ $order->payment_method }} (collection not verified)</p></div></div><section class="box row"><div><strong>Ship to</strong><p>{{ $order->customer_name }}</p><p>{{ $order->phone }}</p>@if($order->email)<p>{{ $order->email }}</p>@endif<p>{{ $order->address }}@if($order->district), {{ $order->district }}@endif</p></div><div><strong>Delivery</strong><p>{{ $order->deliveryZone?->name ?? 'Standard delivery' }}</p><p>Status: {{ $order->status }}</p></div></section><table><thead><tr><th>Item</th><th>Quantity</th><th>Unit price (BDT)</th>@if($document === 'invoice')<th>Total (BDT)</th>@endif</tr></thead><tbody>@foreach($order->items as $item)<tr><td>{{ $item->product_name }}</td><td>{{ $item->quantity }}</td><td>{{ number_format((float)$item->unit_price, 2) }}</td>@if($document === 'invoice')<td>{{ number_format((float)$item->line_total, 2) }}</td>@endif</tr>@endforeach</tbody></table>@if($document === 'invoice')<div class="total"><div><span>Subtotal</span><span>BDT {{ number_format((float)$order->subtotal, 2) }}</span></div><div><span>Delivery</span><span>BDT {{ number_format((float)$order->delivery_fee, 2) }}</span></div><div><strong>Total</strong><strong>BDT {{ number_format((float)$order->total, 2) }}</strong></div></div>@endif @if($order->notes)<section class="box"><strong>Customer note</strong><p>{{ $order->notes }}</p></section>@endif</main></body></html>
